cd <repo>/runs/opus55/ws/024_edit-form-advanced; mkdir -p scratch; cat > scratch/fix.php <<'EOF'
<?php
$f = 'subjects/migrated/opus_5_5/024_edit-form-advanced.php';
$s = file_get_contents($f);
$r = [
 "\$_SERVER['HTTP_USER_AGENT'] )" => "(string) \$_SERVER['HTTP_USER_AGENT'] )",
 '$action = isset($action) ? $action : \'\';' => '$action ??= \'\';',
 "0 === strpos( \$post->post_mime_type, 'audio/' )" => "str_starts_with( (string) \$post->post_mime_type, 'audio/' )",
 "0 === strpos( \$post->post_mime_type, 'video/' )" => "str_starts_with( (string) \$post->post_mime_type, 'video/' )",
 'strtotime( $post->post_date )' => 'strtotime( (string) $post->post_date )',
 "\t\treset( \$revisions ); // Reset pointer for key()\n" => '',
 "'revision_id' => key( \$revisions )" => "'revision_id' => array_key_first( \$revisions )",
 'htmlspecialchars( $post->post_title )' => 'htmlspecialchars( (string) $post->post_title )',
];
foreach ($r as $a => $b) { if (!str_contains($s, $a)) echo "MISS: $a\n"; $s = str_replace($a, $b, $s); }
// long arrays -> short arrays via tokenizer
$t = token_get_all($s); $out=''; $stack=[]; $depth=0; $pending=false;
foreach ($t as $i=>$tok) {
  if (is_array($tok) && $tok[0]===T_ARRAY) { // check next non-ws is '('
    $j=$i+1; while(is_array($t[$j]) && $t[$j][0]===T_WHITESPACE) $j++;
    if ($t[$j]==='(') { $pending=true; continue; }
  }
  if ($tok==='(') { if ($pending) { $stack[]=true; $out.='['; $pending=false; continue; } $stack[]=false; }
  elseif ($tok===')') { if (array_pop($stack)) { $out.=']'; continue; } }
  elseif ($pending && is_array($tok) && $tok[0]===T_WHITESPACE) continue;
  $out .= is_array($tok)?$tok[1]:$tok;
}
file_put_contents($f, $out);
EOF
tools/php scratch/fix.php; tools/lint; tools/rector; tools/test 2>&1 | tail -3
